        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def is_cool(n):
    """
    Checks if n is a cool integer using backtracking search.
    A number is cool if there exists a permutation (x_1, ..., x_n) 
    of (1, ..., n) such that no prefix sum is a perfect square.
    """
    if n <= 0:
        return False

    # State: (current_sum, used_mask/set)
    # We use a set for 'used' numbers for clarity, though a bitmask might be faster for N<=30.

    memo = {} # Memoization might be useful, although the state space is complex. Let's rely on pruning first.

    def backtrack(current_sum, used):
        if len(used) == n:
            # Found a valid permutation of length n
            return True

        # Iterate over all possible next numbers k
        for k in range(1, n + 1):
            if k not in used:
                next_sum = current_sum + k

                if not is_square(next_sum):
                    # Try this choice
                    new_used = used | {k}
                    if backtrack(next_sum, new_used):
                        return True

        return False

    # Start the search. Initial sum is 0, no numbers used.
    return backtrack(0, set())

