def is_square(k):
    if k < 0:
        return False
    sqrt_k = int(k**0.5)
    return sqrt_k * sqrt_k == k

def check_triangular(n):
    sum_n = n * (n + 1) // 2
    return sum_n, is_square(sum_n)

