import math
from itertools import permutations

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

# Function to test if N is cool. Due to time/complexity constraints, this will be highly limited.
# For N up to ~10, we can run full permutation check. For larger N, we will test limited depth.
def check_cool_limited(n, max_depth=10):
    # If N is small enough, run full search
    if n <= 10:
        elements = list(range(1, n + 1))
        for p in permutations(elements):
            prefix_sum = 0
            is_cool_perm = True
            for i in range(n):
                prefix_sum += p[i]
                if is_perfect_square(prefix_sum):
                    is_cool_perm = False
                    break
            if is_cool_perm:
                return True
        return False

    # For larger N, use limited depth search (Backtracking)

    def backtrack(current_permutation, current_sum, available_numbers, depth):
        if depth > max_depth:
            # We stop the search here for time constraints. If a solution hasn't been found,
            # we tentatively assume it is cool, as finding a counterexample requires exhaustiveness.
            # This is a heuristic interpretation of "limited search".
            return True 

        if depth == n:
            return True # Found a full cool permutation

        # Check potential next numbers
        for next_num in list(available_numbers):
            new_sum = current_sum + next_num
            if not is_perfect_square(new_sum):
                new_available = available_numbers - {next_num}
                if backtrack(current_permutation + [next_num], new_sum, new_available, depth + 1):
                    return True
        return False

    # Start the search
    available = set(range(1, n + 1))
    return backtrack([], 0, available, 0)

